import { getSurveilansById } from "@/services/surveilans";
import { redirect } from "next/navigation";
import { ArrowLeft, Save, AlertCircle } from "lucide-react";
import Link from "next/link";

export const dynamic = "force-dynamic";

export default async function EditRiwayatPage({ params }: { params: { id: string } }) {
  const { id } = await params;
  const data = await getSurveilansById(id);

  if (!data) redirect("/dashboard/perawat/riwayat");

  return (
    <div className="space-y-6 text-slate-600">
      {/* Header navigasi */}
      <div className="flex items-center gap-4">
        <Link 
          href="/dashboard/perawat/riwayat"
          className="p-2 bg-white border border-slate-100 rounded-xl text-slate-400 hover:text-blue-600 transition-all"
        >
          <ArrowLeft size={20} />
        </Link>
        <div>
          <h1 className="text-xl font-semibold text-slate-800 tracking-tight">Edit Laporan Surveilans</h1>
          <p className="text-sm font-medium text-slate-500 uppercase">
            Pasien: {data.nama_pasien} | RM: {data.no_rm}
          </p>
        </div>
      </div>

      <div className="bg-amber-50 border border-amber-100 p-4 rounded-2xl flex gap-3 items-center">
        <AlertCircle size={18} className="text-amber-600" />
        <p className="text-xs font-medium text-amber-700">
          Perubahan pada laporan ini akan langsung memperbarui data analitik PPI RS Arun.
        </p>
      </div>

      <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-[0_8px_30px_rgb(0,0,0,0.02)]">
        {/* Form Client Component dimasukkan di sini */}
        {/* Pastikan mengirimkan data lama sebagai initialData */}
        <div className="space-y-4">
           <p className="text-sm font-medium text-slate-400 italic">
            Silakan hubungkan dengan komponen Form yang sudah ada, 
            lalu panggil fungsi updateSurveilans saat form dikirim.
          </p>
        </div>
        
        <div className="mt-8 flex justify-end gap-3">
          <Link 
            href="/dashboard/perawat/riwayat"
            className="px-6 py-3 rounded-xl font-medium text-slate-500 hover:bg-slate-50 transition-all"
          >
            Batal
          </Link>
          <button className="flex items-center gap-2 bg-blue-600 text-white px-8 py-3 rounded-xl font-medium hover:bg-blue-700 transition-all shadow-lg shadow-blue-100">
            <Save size={18} />
            Simpan Perubahan
          </button>
        </div>
      </div>
    </div>
  );
}